package io.mavsdk.kotlin.plugins.offboard

import io.mavsdk.kotlin.System
import kotlin.coroutines.resume
import kotlinx.coroutines.suspendCancellableCoroutine

/**
 * Control a drone with position, velocity, attitude or motor commands.
 *
 * The module is called offboard because the commands can be sent from external sources as opposed
 * to onboard control right inside the autopilot "board".
 *
 * Client code must specify a setpoint before starting offboard mode. Mavsdk automatically sends
 * setpoints at 20Hz (PX4 Offboard mode requires that setpoints are minimally sent at 2Hz).
 */
class Offboard internal constructor(private val native: OffboardNative) : AutoCloseable {
    private var closed = false

    /** Possible results returned for offboard requests */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** No system is connected */
        NO_SYSTEM(2),
        /** Connection error */
        CONNECTION_ERROR(3),
        /** Vehicle is busy */
        BUSY(4),
        /** Command denied */
        COMMAND_DENIED(5),
        /** Request timed out */
        TIMEOUT(6),
        /** Cannot start without setpoint set */
        NO_SETPOINT_SET(7),
        /** Request failed */
        FAILED(8);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /** Possible altitude options */
    enum class AltitudeType(val value: Int) {
        /** Altitude relative to the Home position */
        REL_HOME(0),
        /** Altitude above mean sea level (AMSL) */
        AMSL(1),
        /** Altitude above ground level (AGL) */
        AGL(2);

        companion object {
            fun fromValue(value: Int): AltitudeType =
                entries.find { it.value == value } ?: entries.first()
        }
    }

    /**
     * Type for attitude body angles in NED reference frame (roll, pitch, yaw and thrust)
     *
     * @property rollDeg Roll angle (in degrees, positive is right side down)
     * @property pitchDeg Pitch angle (in degrees, positive is nose up)
     * @property yawDeg Yaw angle (in degrees, positive is move nose to the right)
     * @property thrustValue Thrust (range: 0 to 1)
     */
    data class Attitude(
        val rollDeg: Float,
        val pitchDeg: Float,
        val yawDeg: Float,
        val thrustValue: Float,
    )

    /**
     * Eight controls that will be given to the group. Each control is a normalized (-1..+1) command
     * value, which will be mapped and scaled through the mixer.
     *
     * @property controls Controls in the group
     */
    data class ActuatorControlGroup(val controls: List<Float> = emptyList())

    /**
     * Type for actuator control.
     *
     * Control members should be normed to -1..+1 where 0 is neutral position. Throttle for single
     * rotation direction motors is 0..1, negative range for reverse direction.
     *
     * One group support eight controls.
     *
     * Up to 16 actuator controls can be set. To ignore an output group, set all it controls to NaN.
     * If one or more controls in group is not NaN, then all NaN controls will sent as zero. The
     * first 8 actuator controls internally map to control group 0, the latter 8 actuator controls
     * map to control group 1. Depending on what controls are set (instead of NaN) 1 or 2 MAVLink
     * messages are actually sent.
     *
     * In PX4 v1.9.0 Only first four Control Groups are supported
     * (https://github.com/PX4/PX4-Autopilot/blob/v1.9.0/src/modules/mavlink/mavlink_receiver.cpp#L980).
     *
     * @property groups Control groups.
     */
    data class ActuatorControl(val groups: List<ActuatorControlGroup> = emptyList())

    /**
     * Type for attitude rate commands in body coordinates (roll, pitch, yaw angular rate and
     * thrust)
     *
     * @property rollDegS Roll angular rate (in degrees/second, positive for clock-wise looking from
     *   front)
     * @property pitchDegS Pitch angular rate (in degrees/second, positive for head/front moving up)
     * @property yawDegS Yaw angular rate (in degrees/second, positive for clock-wise looking from
     *   above)
     * @property thrustValue Thrust (range: 0 to 1)
     */
    data class AttitudeRate(
        val rollDegS: Float,
        val pitchDegS: Float,
        val yawDegS: Float,
        val thrustValue: Float,
    )

    /**
     * Type for position commands in NED (North East Down) coordinates and yaw.
     *
     * @property northM Position North (in metres)
     * @property eastM Position East (in metres)
     * @property downM Position Down (in metres)
     * @property yawDeg Yaw in degrees (0 North, positive is clock-wise looking from above)
     */
    data class PositionNedYaw(
        val northM: Float,
        val eastM: Float,
        val downM: Float,
        val yawDeg: Float,
    )

    /**
     * Type for position commands in Global (Latitude, Longitude, Altitude) coordinates and yaw.
     *
     * @property latDeg Latitude (in degrees)
     * @property lonDeg Longitude (in degrees)
     * @property altM altitude (in metres)
     * @property yawDeg Yaw in degrees (0 North, positive is clock-wise looking from above)
     * @property altitudeType altitude type for this position
     */
    data class PositionGlobalYaw(
        val latDeg: Double,
        val lonDeg: Double,
        val altM: Float,
        val yawDeg: Float,
        val altitudeType: AltitudeType,
    )

    /**
     * Type for velocity commands in body coordinates.
     *
     * @property forwardMS Velocity forward (in metres/second)
     * @property rightMS Velocity right (in metres/second)
     * @property downMS Velocity down (in metres/second)
     * @property yawspeedDegS Yaw angular rate (in degrees/second, positive for clock-wise looking
     *   from above)
     */
    data class VelocityBodyYawspeed(
        val forwardMS: Float,
        val rightMS: Float,
        val downMS: Float,
        val yawspeedDegS: Float,
    )

    /**
     * Type for velocity commands in NED (North East Down) coordinates and yaw.
     *
     * @property northMS Velocity North (in metres/second)
     * @property eastMS Velocity East (in metres/second)
     * @property downMS Velocity Down (in metres/second)
     * @property yawDeg Yaw in degrees (0 North, positive is clock-wise looking from above)
     */
    data class VelocityNedYaw(
        val northMS: Float,
        val eastMS: Float,
        val downMS: Float,
        val yawDeg: Float,
    )

    /**
     * Type for acceleration commands in NED (North East Down) coordinates.
     *
     * @property northMS2 Acceleration North (in metres/second^2)
     * @property eastMS2 Acceleration East (in metres/second^2)
     * @property downMS2 Acceleration Down (in metres/second^2)
     */
    data class AccelerationNed(val northMS2: Float, val eastMS2: Float, val downMS2: Float)

    /**
     * Start offboard control.
     *
     * @return The result of the request.
     */
    suspend fun start(): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = OffboardCallbackGuard()
        native.startAsync() { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && true && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Stop offboard control.
     *
     * The vehicle will be put into Hold mode: https://docs.px4.io/main/en/flight_modes_mc/hold.html
     *
     * @return The result of the request.
     */
    suspend fun stop(): Result = suspendCancellableCoroutine { continuation ->
        val callbackGuard = OffboardCallbackGuard()
        native.stopAsync() { result ->
            val parsedResult = Result.fromValue(result)
            if (continuation.isActive && true && callbackGuard.tryClaim()) {
                continuation.resume(parsedResult)
            }
        }
    }

    /**
     * Check if offboard control is active.
     *
     * True means that the vehicle is in offboard mode and we are actively sending setpoints.
     *
     * @return True if offboard is active
     */
    fun isActive(): Boolean = native.isActive()

    /**
     * Set the attitude in terms of roll, pitch and yaw in degrees with thrust.
     *
     * @param attitude Attitude roll, pitch and yaw along with thrust
     * @return The result of the request.
     */
    fun setAttitude(attitude: Attitude): Result = Result.fromValue(native.setAttitude(attitude))

    /**
     * Set direct actuator control values to groups #0 and #1.
     *
     * First 8 controls will go to control group 0, the following 8 controls to control group 1 (if
     * actuator_control.num_controls more than 8).
     *
     * @param actuatorControl Actuator control values
     * @return The result of the request.
     */
    fun setActuatorControl(actuatorControl: ActuatorControl): Result =
        Result.fromValue(native.setActuatorControl(actuatorControl))

    /**
     * Set the attitude rate in terms of pitch, roll and yaw angular rate along with thrust.
     *
     * @param attitudeRate Attitude rate roll, pitch and yaw angular rate along with thrust
     * @return The result of the request.
     */
    fun setAttitudeRate(attitudeRate: AttitudeRate): Result =
        Result.fromValue(native.setAttitudeRate(attitudeRate))

    /**
     * Set the position in NED coordinates and yaw.
     *
     * @param positionNedYaw Position and yaw
     * @return The result of the request.
     */
    fun setPositionNed(positionNedYaw: PositionNedYaw): Result =
        Result.fromValue(native.setPositionNed(positionNedYaw))

    /**
     * Set the position in Global coordinates (latitude, longitude, altitude) and yaw
     *
     * @param positionGlobalYaw Position and yaw
     * @return The result of the request.
     */
    fun setPositionGlobal(positionGlobalYaw: PositionGlobalYaw): Result =
        Result.fromValue(native.setPositionGlobal(positionGlobalYaw))

    /**
     * Set the velocity in body coordinates and yaw angular rate. Not available for fixed-wing
     * aircraft.
     *
     * @param velocityBodyYawspeed Velocity and yaw angular rate
     * @return The result of the request.
     */
    fun setVelocityBody(velocityBodyYawspeed: VelocityBodyYawspeed): Result =
        Result.fromValue(native.setVelocityBody(velocityBodyYawspeed))

    /**
     * Set the velocity in NED coordinates and yaw. Not available for fixed-wing aircraft.
     *
     * @param velocityNedYaw Velocity and yaw
     * @return The result of the request.
     */
    fun setVelocityNed(velocityNedYaw: VelocityNedYaw): Result =
        Result.fromValue(native.setVelocityNed(velocityNedYaw))

    /**
     * Set the position in NED coordinates, with the velocity to be used as feed-forward.
     *
     * @param positionNedYaw Position and yaw
     * @param velocityNedYaw Velocity and yaw
     * @return The result of the request.
     */
    fun setPositionVelocityNed(
        positionNedYaw: PositionNedYaw,
        velocityNedYaw: VelocityNedYaw,
    ): Result = Result.fromValue(native.setPositionVelocityNed(positionNedYaw, velocityNedYaw))

    /**
     * Set the position, velocity and acceleration in NED coordinates, with velocity and
     * acceleration used as feed-forward.
     *
     * @param positionNedYaw Position and yaw
     * @param velocityNedYaw Velocity and yaw
     * @param accelerationNed Acceleration
     * @return The result of the request.
     */
    fun setPositionVelocityAccelerationNed(
        positionNedYaw: PositionNedYaw,
        velocityNedYaw: VelocityNedYaw,
        accelerationNed: AccelerationNed,
    ): Result =
        Result.fromValue(
            native.setPositionVelocityAccelerationNed(
                positionNedYaw,
                velocityNedYaw,
                accelerationNed,
            )
        )

    /**
     * Set the acceleration in NED coordinates.
     *
     * @param accelerationNed Acceleration
     * @return The result of the request.
     */
    fun setAccelerationNed(accelerationNed: AccelerationNed): Result =
        Result.fromValue(native.setAccelerationNed(accelerationNed))

    override fun close() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class OffboardException(val result: Result, message: String) : Exception(message)

    companion object {
        fun create(system: System): Offboard =
            Offboard(createOffboardNative(system.getHandle())).also { system.registerPlugin(it) }
    }
}

internal interface OffboardNative {
    fun startAsync(callback: (Int) -> Unit)

    fun stopAsync(callback: (Int) -> Unit)

    fun isActive(): Boolean

    fun setAttitude(attitude: Offboard.Attitude): Int

    fun setActuatorControl(actuatorControl: Offboard.ActuatorControl): Int

    fun setAttitudeRate(attitudeRate: Offboard.AttitudeRate): Int

    fun setPositionNed(positionNedYaw: Offboard.PositionNedYaw): Int

    fun setPositionGlobal(positionGlobalYaw: Offboard.PositionGlobalYaw): Int

    fun setVelocityBody(velocityBodyYawspeed: Offboard.VelocityBodyYawspeed): Int

    fun setVelocityNed(velocityNedYaw: Offboard.VelocityNedYaw): Int

    fun setPositionVelocityNed(
        positionNedYaw: Offboard.PositionNedYaw,
        velocityNedYaw: Offboard.VelocityNedYaw,
    ): Int

    fun setPositionVelocityAccelerationNed(
        positionNedYaw: Offboard.PositionNedYaw,
        velocityNedYaw: Offboard.VelocityNedYaw,
        accelerationNed: Offboard.AccelerationNed,
    ): Int

    fun setAccelerationNed(accelerationNed: Offboard.AccelerationNed): Int

    fun destroy()
}

internal expect fun createOffboardNative(systemHandle: Long): OffboardNative

internal expect class OffboardCallbackGuard() {
    fun tryClaim(): Boolean
}
